import{_ as s}from"./chunks/datacopy_address_overlap_sync_diagram.Beodm7Hh.js";import{_ as t,o as n,a as p,b as e}from"./app.DKoEZOcr.js";const I=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"数据搬运导览","link":"/api/SIMD-API/basic_api/data_move_guide/data_move_guide"},{"text":"概览","link":"/api/SIMD-API/basic_api/data_move_guide/overview/overview"},{"text":"总体约束说明","link":"/api/SIMD-API/basic_api/data_move_guide/overview/overall_constraints"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/data_move_guide/overview/overall_constraints.md","filePath":"api/SIMD-API/basic_api/data_move_guide/overview/overall_constraints.md","outlineHeaders":[{"level":2,"title":"地址对齐约束","slug":"地址对齐约束","link":"#地址对齐约束"},{"level":2,"title":"多指令同步","slug":"多指令同步","link":"#多指令同步"}],"lastUpdated":1787050286000}'),l={name:"api/SIMD-API/basic_api/data_move_guide/overview/overall_constraints.md"};function i(c,a,r,d,o,_){return n(),p("div",null,[...a[0]||(a[0]=[e(`<div><article class="markdown-body"><h1>总体约束说明<span id="ZH-CN_TOPIC_0000002565840545"></span></h1><p>所有数据搬运接口共享若干通用约束规则，在进行任何搬运操作前都应确保这些约束被满足，否则可能导致未定义行为或数据异常。</p><h2 id="地址对齐约束">地址对齐约束<span id="section136711917101710"></span><a class="header-anchor" href="#地址对齐约束">​</a></h2><p>AI Core上的各类存储单元有不同的地址对齐要求。Ascend C API操作数的起始地址必须满足对应存储单元的对齐约束。DataBlock（32字节）是搬运操作的基本寻址粒度，大部分搬运接口的blockLen参数均以DataBlock为单位计算。各存储单元的对齐要求如下表所示。</p><p><strong>表 1</strong> <strong>各存储单元地址对齐要求</strong><span id="table16278354141117"></span></p><table><thead><tr><th>存储单元</th><th>对齐要求</th><th>说明</th></tr></thead><tbody><tr><td>Global Memory</td><td>1字节对齐</td><td>最宽松的对齐要求，任意字节地址均可</td></tr><tr><td>UB</td><td>32字节对齐</td><td>与DataBlock大小一致，地址必须为32的整数倍</td></tr><tr><td>L1 Buffer</td><td>32字节对齐</td><td>同UB，地址必须为32的整数倍</td></tr><tr><td>L0A Buffer/L0B Buffer</td><td>512字节对齐</td><td>矩阵计算输入的高对齐要求</td></tr><tr><td>L0C Buffer</td><td>64字节对齐</td><td>矩阵计算结果缓冲区</td></tr><tr><td>BiasTable Buffer</td><td>64字节对齐</td><td>偏置数据缓冲区</td></tr><tr><td>Fixpipe Buffer</td><td>128字节对齐</td><td>量化参数暂存区</td></tr></tbody></table><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>需要注意的是：如果某个具体接口的约束说明中明确指定了与上表不同的对齐要求，则应以该接口自身的说明为准。</li><li>对于不满足对齐要求的场景，应使用DataCopyPad接口的非对齐搬运能力。</li></ul></div><h2 id="多指令同步">多指令同步<span id="section711085812111"></span><a class="header-anchor" href="#多指令同步">​</a></h2><p>如果需要执行多个DataCopy指令，且DataCopy的目的地址存在重叠，需要调用<a href="../../sync_control/intra_core_sync/PipeBarrier_ISASI.html">PipeBarrier</a>插入同步指令，保证多个DataCopy指令的串行化，防止出现异常数据。如下图左侧示意图，执行两个DataCopy指令，搬运的目的GM地址存在重叠，两条搬运指令之间需要通过调用PipeBarrier&lt;PIPE_MTE3&gt;()进行MTE3流水的同步；如下图右侧示意图所示，搬运的目的地址Unified Buffer（UB）存在重叠，两条搬运指令之间需要调用PipeBarrier&lt;PIPE_MTE2&gt;()进行MTE2流水的同步。多指令同步的核心代码示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">src2Local</span><span class="p">,</span><span class="w"> </span><span class="n">src2Global</span><span class="p">,</span><span class="w"> </span><span class="n">srcDataSize</span><span class="p">);</span>
<span class="c1">// 两条搬运指令之间需要调用PipeBarrier&lt;PIPE_MTE2&gt;()添加MTE2搬入流水的同步。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">src1Local</span><span class="p">,</span><span class="w"> </span><span class="n">src1Global</span><span class="p">,</span><span class="w"> </span><span class="n">srcDataSize</span><span class="p">);</span>
<span class="c1">// 输入src1和src2在UB上分配的地址区间有重叠。</span>
<span class="c1">// 为了保证src2的数据不会覆盖src1在重叠区间的值，必须保证先搬入src2，后搬入src1。</span>
</code></pre></div><p><strong>图 1</strong> DataCopy的目的地址存在重叠<span id="fig333145263318"></span></p><p><img src="`+s+'" alt title="DataCopy的目的地址存在重叠"></p></article></div>',1)])])}const P=t(l,[["render",i]]);export{I as __pageData,P as default};
